/* The Quant Paddock — docs: the glossary (#/glossary, #/glossary/<key>, #/glossary/g:<group>)
 * and the methodology document (#/methodology, #/methodology/<section>).
 *
 * The glossary reads data/glossary.json ({groups: [{name, entries}], model: [...]});
 * until that is published it is assembled from the driver and team catalogues.
 * The methodology is static text: every constant in it was read from the Python
 * models under oddsmarkets/f1/ (each paragraph names its source file). */
(function (PD) {
'use strict';

const { esc, muted } = PD;
const PG = () => PD.pg;

// ── glossary ───────────────────────────────────────────────────────────────

function slug(s) { return String(s || 'group').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); }

function loadGlossary() {
  return PD.load('glossary.json').then(g => {
    if (g && g.ok !== false && (g.groups || []).length) return Object.assign({ source: 'payload' }, g);
    const y = PD.currentSeason();
    return PD.loadAll([y + '/drivers.json', y + '/teams.json']).then(res => {
      const groups = [];
      [[res[0], 'Driver: '], [res[1], 'Team: ']].forEach(p => {
        ((p[0] || {}).metrics || []).forEach(m => {
          const name = p[1] + (m.group || 'Other');
          let grp = groups.find(x => x.name === name);
          if (!grp) { grp = { name: name, entries: [] }; groups.push(grp); }
          grp.entries.push(m);
        });
      });
      return { groups: groups, model: [], source: 'catalogue' };
    });
  });
}

function fmtHint(e) {
  const tags = [];
  const f = e.fmt;
  if (f === 'pct') tags.push(['%', '']);
  else if (f === 'prob') tags.push(['probability', '']);
  else if (f === 'int') tags.push(['count', '']);
  else if (f === 'ms' || f === 'gap') tags.push(['time', '']);
  else if (f === 's') tags.push(['seconds', '']);
  if (e.lower) tags.push(['lower is better', 'lower']);
  if (e.scope) tags.push([String(e.scope), '']);
  return tags.map(t => '<span class="gl-tag' + (t[1] ? ' ' + t[1] : '') + '">' + esc(t[0]) + '</span>').join('');
}

function entryHTML(e, isModel) {
  const q = [e.label, e.key, e.desc, e.group, isModel ? 'model' : ''].join(' ').toLowerCase();
  return '<div class="gl-entry" id="gl-' + esc(e.key) + '" data-q="' + esc(q) + '">' +
    '<dt><span>' + esc(e.label || e.key) + ' <a class="doc-anchor" href="#/glossary/' + encodeURIComponent(e.key) + '" title="Link to this entry">#</a></span>' +
    '<span class="gl-tags"><span class="gl-key">' + esc(e.key) + '</span>' + (isModel ? '<span class="gl-tag model">model</span>' : fmtHint(e)) + '</span></dt>' +
    '<dd>' + (e.desc ? esc(e.desc) : '<span class="muted-inline">No definition yet.</span>') + '</dd></div>';
}

function renderGlossary(el, params) {
  const key = (params.rest || [])[0] || '';
  el.innerHTML = '<div id="glossary-root">' + muted('Loading the glossary…') + '</div>';
  return loadGlossary().then(g => {
    const root = document.getElementById('glossary-root');
    if (!root || !PG().alive(el)) return;
    const groups = g.groups || [];
    const modelGroups = [];
    (g.model || []).forEach(t => {
      const name = t.group || 'Model';
      let grp = modelGroups.find(x => x.name === name);
      if (!grp) { grp = { name: name, entries: [] }; modelGroups.push(grp); }
      grp.entries.push(t);
    });
    const nMetrics = groups.reduce((s, x) => s + (x.entries || []).length, 0);
    const nModel = modelGroups.reduce((s, x) => s + x.entries.length, 0);
    if (!nMetrics && !nModel) { root.innerHTML = PD.card('Glossary', '', PG().notBuilt('The glossary', null)); return; }
    const index = groups.map(x => '<a href="#/glossary/g:' + esc(slug(x.name)) + '" data-group="' + esc(slug(x.name)) + '">' + esc(x.name) + '</a>').join('') +
      modelGroups.map(x => '<a href="#/glossary/g:model-' + esc(slug(x.name)) + '" data-group="model-' + esc(slug(x.name)) + '">' + esc(x.name) + '</a>').join('');
    const cardOf = (name, sl, entries, isModel) => '<div class="card gl-group" data-group="' + esc(sl) + '"><div class="card-header">' + esc(name) + ' <span class="card-sub">' + entries.length + '</span></div><dl class="gl-list">' + entries.map(e => entryHTML(e, isModel)).join('') + '</dl></div>';
    root.innerHTML =
      '<div class="card"><div class="card-header">Glossary <span class="card-sub">Every metric the site computes and every model term it uses. How they are computed is in the <a href="#/methodology">methodology</a>.</span></div>' +
      '<div class="gl-top"><input id="gl-search" type="search" placeholder="Filter the glossary…" autocomplete="off" spellcheck="false"><span class="gl-count" id="gl-count"></span></div>' +
      '<div class="gl-index">' + index + '</div>' +
      '<div class="doc-meta">' + nMetrics + ' metrics in ' + groups.length + ' groups' + (nModel ? ' and ' + nModel + ' model terms' : '') + (g.updated_at ? ' · updated ' + esc(PD.fmtStamp(g.updated_at)) : '') +
      (g.source === 'catalogue' ? ' · assembled from the driver and team catalogues until data/glossary.json is published' : '') + '</div></div>' +
      groups.map(x => cardOf(x.name, slug(x.name), x.entries || [], false)).join('') +
      modelGroups.map(x => cardOf('Model terms: ' + x.name, 'model-' + slug(x.name), x.entries, true)).join('') +
      '<div class="card gl-empty" id="gl-none" style="display:none">Nothing in the glossary matches that.</div>';
    const input = document.getElementById('gl-search');
    const count = document.getElementById('gl-count');
    const entries = Array.prototype.slice.call(root.querySelectorAll('.gl-entry'));
    const cards = Array.prototype.slice.call(root.querySelectorAll('.gl-group'));
    const total = entries.length;
    const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
    const filter = () => {
      const needle = norm(input.value.trim());
      let shown = 0;
      entries.forEach(e => { const hit = !needle || norm(e.dataset.q).indexOf(needle) >= 0; e.classList.toggle('hidden', !hit); if (hit) shown++; });
      cards.forEach(c => c.classList.toggle('hidden', !c.querySelector('.gl-entry:not(.hidden)')));
      document.getElementById('gl-none').style.display = shown ? 'none' : '';
      count.textContent = needle ? shown + ' of ' + total + ' entries' : total + ' entries';
    };
    input.addEventListener('input', filter);
    input.addEventListener('keydown', ev => { if (ev.key === 'Escape') { input.value = ''; filter(); } });
    filter();
    root.querySelectorAll('.gl-index a').forEach(a => a.addEventListener('click', ev => {
      ev.preventDefault();
      const grp = root.querySelector('.gl-group[data-group="' + a.dataset.group + '"]');
      if (grp) { grp.classList.remove('hidden'); grp.scrollIntoView({ block: 'start' }); }
      history.replaceState(null, '', a.getAttribute('href'));
    }));
    // Deep link.
    if (key) {
      if (key.indexOf('g:') === 0) {
        const grp = root.querySelector('.gl-group[data-group="' + key.slice(2).replace(/"/g, '') + '"]');
        if (grp) setTimeout(() => grp.scrollIntoView({ block: 'start' }), 0);
      } else {
        const e = document.getElementById('gl-' + key);
        if (e) { e.classList.add('hit'); setTimeout(() => e.scrollIntoView({ block: 'center' }), 50); setTimeout(() => e.scrollIntoView({ block: 'center' }), 400); }
      }
    }
  });
}

// ── methodology ────────────────────────────────────────────────────────────

const METHOD_HTML = "<section id=\"m-data\">\n<h2>Data sources and refresh</h2>\n<p>The site combines two public F1 data services. Jolpica, the community successor to the Ergast API, provides the historical record: calendars, race results, qualifying, sprint results, pit stops and lap times. OpenF1 provides richer per-session data from 2023: lap and sector times, tyre stints, pit-lane times, race-control messages, weather, overtakes and car telemetry. Neither service needs an API key.</p>\n\n<h3>Jolpica</h3>\n<p>Requests go to <code>https://api.jolpi.ca/ergast/f1</code>. Jolpica enforces 4 requests a second in a burst and 500 an hour sustained, per IP address, and answers HTTP 429 when they are exceeded. One pacer handles every call. By default it spaces calls 7.3 seconds apart, which keeps under the hourly cap, and stops after 450 calls. Each call is tried up to 5 times. After a 429 it waits for the Retry-After header, or 60 s times the attempt number when the header is missing. After a network error it waits 10 s times the attempt number, and after any other non-200 status 5 s times the attempt number. A 404 means no data. Pages hold at most 100 rows, and the client walks <code>offset</code> until it reaches the reported <code>total</code>.</p>\n<span class=\"src\">sources/jolpica.py</span>\n<p>The parsers flatten Ergast's nested JSON into records keyed by Jolpica ids and convert every time to integer milliseconds. A lap or qualifying time such as \"1:23.456\" or \"83.456\" becomes 83456. Each result row holds driver, constructor, car number, grid, position, position_text, points, laps, status, race time, and the fastest-lap rank, lap and time. Each qualifying row holds driver, constructor, number, position and the Q1, Q2 and Q3 times. Each race record holds the name, date, time, the circuit (id, name, locality, country, latitude, longitude) and the session start times (fp1, fp2, fp3, quali, sprint, sprint_quali; Sprint Shootout maps to sprint_quali).</p>\n<span class=\"src\">sources/jolpica.py</span>\n<p>The fetch script fills one store per season in four phases. Every phase runs over every season, newest season first, and skips anything already stored.</p>\n<ul>\n<li><code>schedule</code>: the calendar, one call per season. A finished season is fetched once.</li>\n<li><code>results</code>: race results, qualifying, and sprint results from 2021, read through paged calls.</li>\n<li><code>pitstops</code>: from 2011, one paged call per race that has results.</li>\n<li><code>laps</code>: from 1996, lap times and positions at the end of each lap, per race. A race for which Jolpica returns no laps is marked as done so it is not requested again.</li>\n</ul>\n<p>A race counts as finished 4 hours after its scheduled start. The <code>--refresh-current</code> flag re-fetches every phase for the current season's finished rounds. The full history takes about 7,000 calls, which at the default pacing is roughly 14 hours, and the script can be stopped and restarted at any point.</p>\n<span class=\"src\">scripts/f1_fetch.py</span>\n\n<h3>OpenF1</h3>\n<p>Requests go to <code>https://api.openf1.org/v1</code>. The client spaces calls 0.35 s apart, stops after a budget of calls (2,000 by default in the client, overridden by the scripts), and tries each call up to 5 times. After a 429 it waits for Retry-After, or 20 s times the attempt number. OpenF1 answers 404 for an empty query, so a 404 is read as an empty list. OpenF1 sends permissive CORS headers, so the site's browser code can also fetch raw lap telemetry directly.</p>\n<span class=\"src\">sources/openf1.py</span>\n<p>Each session is stored as one compact JSON record at <code>docs/paddock/data/&lt;year&gt;/sessions/&lt;session_key&gt;.json</code>. Every time inside a session is in milliseconds from the session's <code>date_start</code>. The record contains:</p>\n<ul>\n<li><code>session</code>: session_key, meeting_key, session_name, session_type, date_start, date_end, circuit_key, circuit_short_name, country_name, location, year.</li>\n<li><code>drivers</code>, keyed by car number: broadcast_name, full_name, name_acronym, first_name, last_name, team_name, team_colour, country_code.</li>\n<li><code>laps</code>, keyed by car number. Each row is <code>[lap, t_start_ms, lap_ms, s1_ms, s2_ms, s3_ms, i1_kph, i2_kph, speedtrap_kph, pit_out]</code>. pit_out is 1 on a pit-out lap and 0 otherwise. Rows are sorted by lap number.</li>\n<li><code>lap_end</code>, race sessions only, keyed by car number. Each row is <code>[lap, gap_to_leader, interval]</code>, taken from the last OpenF1 interval sample at or before the end of the lap (lap start plus lap duration).</li>\n<li><code>stints</code>: rows of <code>[driver_number, stint, lap_start, lap_end, compound, tyre_age_at_start]</code>.</li>\n<li><code>pit</code>: rows of <code>[driver_number, lap, t_ms, lane_ms, stop_ms]</code>. lane_ms comes from lane_duration, or from pit_duration when lane_duration is missing.</li>\n<li><code>race_control</code>: rows of <code>[t_ms, lap, category, flag, scope, sector, driver_number, message]</code>.</li>\n<li><code>weather</code>: rows of <code>[t_ms, air_c, track_c, humidity, rainfall, wind_speed, wind_dir, pressure]</code>.</li>\n<li>For race, qualifying and sprint sessions only: <code>overtakes</code> as <code>[t_ms, overtaking_number, overtaken_number, position]</code>; <code>result</code> as objects with position, driver_number, number_of_laps, points, dnf, dns, dsq, duration and gap_to_leader; <code>grid</code> as <code>[position, driver_number, lap_ms]</code>; and <code>positions</code>, keyed by car number, as <code>[t_ms, position]</code> at each position change.</li>\n<li><code>fetched_at</code>: the UTC time of the fetch.</li>\n</ul>\n<span class=\"src\">sources/openf1.py</span>\n<p>Raw telemetry is fetched for each driver from the <code>car_data</code> and <code>location</code> endpoints. The feed runs all day, so only samples from 5 minutes before the session start to 5 minutes after its end are kept. They are stored as gzipped column arrays at <code>data/f1/telemetry/&lt;year&gt;/&lt;session_key&gt;/&lt;driver&gt;.json.gz</code>: <code>car</code> holds t, speed, rpm, gear, throttle, brake and drs, and <code>loc</code> holds t, x, y and z. These raw files are not committed to git. The browser can fetch any single lap from <code>car_data</code> by the lap's time window, which it computes as the session date_start plus the lap's t_start_ms, up to that point plus lap_ms.</p>\n<span class=\"src\">sources/openf1.py</span><span class=\"src\">PAYLOADS.md</span>\n<p>The OpenF1 script fetches a session only after it has ended plus a settling margin of 1,800 s. It fetches the session again on every run while the session is younger than <code>--refresh-hours</code> (default 48), so late corrections are picked up. With <code>--telemetry</code> it also fetches each driver's raw telemetry, skipping files already on disk unless the session is still young.</p>\n<span class=\"src\">scripts/f1_openf1.py</span>\n\n<h3>Season store</h3>\n<p>Each season has one JSON store at <code>docs/paddock/data/&lt;year&gt;/store.json</code>, which is the single source of truth for the build. It holds <code>races</code> keyed by round (calendar, results, qualifying, sprint, pitstops, <code>laps</code> as one list of milliseconds per driver with null for a missing lap, and <code>positions</code> as one list of positions per driver), <code>drivers</code> (code, number, given, family, dob, nationality), <code>constructors</code> (name, nationality) and <code>meta</code>, which records when each part of each round was fetched. The store is written to a temporary file and then renamed into place, so a reader never sees a half-written store.</p>\n<span class=\"src\">store.py</span>\n\n<h3>Update cadence</h3>\n<p>A GitHub Actions workflow runs every hour at minute 37. Each run does the following in order:</p>\n<ul>\n<li>Fetches Jolpica with <code>--refresh-current</code>, a budget of 120 calls and an interval of 1.0 s.</li>\n<li>Fetches the current year's OpenF1 sessions and telemetry with a budget of 3,000 calls.</li>\n<li>Summarises the telemetry.</li>\n<li>Builds the site.</li>\n<li>Commits the changed stores, session files and telemetry summaries.</li>\n<li>Deploys <code>docs/paddock/</code>.</li>\n</ul>\n<p>Raw telemetry is carried between runs in the Actions cache. The fetch steps are allowed to fail without stopping the build. In practice the site's data changes after each session ends: OpenF1 sessions become eligible 30 minutes after they end, and Jolpica rounds are refreshed as soon as Jolpica publishes them.</p>\n<span class=\"src\">.github/workflows/update_paddock.yml</span>\n</section>\n\n<section id=\"m-identity\">\n<h2>Identity</h2>\n<p>Everything on the site keys drivers by Jolpica <code>driverId</code> (for example max_verstappen), teams by <code>constructorId</code> (for example red_bull) and circuits by <code>circuitId</code>. These ids come straight from Jolpica and do not change across seasons.</p>\n<span class=\"src\">CONTRACT.md</span>\n<h3>Car numbers</h3>\n<p>Car numbers are resolved to drivers separately for each season, because a number can change hands between seasons (No. 1 belongs to the champion, and retired numbers are reissued). A season's map is built from the number field of its results, qualifying and sprint rows. Each number goes to the driver who carried it in the most rows. A permanent number from the season's driver list is used only for a number that no row claims. When the round is known, a round-level map from that round's rows is tried first, and that map is exact. A substitute therefore resolves correctly, and a number that two drivers used in one season is resolved per round.</p>\n<span class=\"src\">canon.py</span>\n<h3>Teams</h3>\n<p>A driver's team at a round is the constructor on his row for that round. If he has no row there, the nearest round is used, earlier rounds first and then later ones. A round's lineup is taken from its qualifying, results and sprint entries. For a round that has not run yet, the lineup of the most recent earlier round is used.</p>\n<span class=\"src\">canon.py</span>\n<h3>Mapping OpenF1 sessions</h3>\n<p>An OpenF1 session is assigned to the round whose race date falls 0 to 4 days on or after the session date. The closest such round wins. Each car number in a session record is then mapped to a driverId:</p>\n<ul>\n<li>by number within that round, then within the season;</li>\n<li>if the number is unknown, by matching the OpenF1 three-letter name_acronym against the season's driver codes;</li>\n<li>failing that, by matching last_name against family names.</li>\n</ul>\n<p>Numbers that still cannot be resolved are dropped. None of these lookups raises an error on missing data.</p>\n<span class=\"src\">canon.py</span>\n</section>\n\n<section id=\"m-laptime\">\n<h2>Race lap-time model</h2>\n<p>For each Grand Prix the lap-time model estimates every driver's corrected race pace in seconds per lap. Pace is measured relative to the field mean, and a negative value means faster. The model is fitted to clean laps only. OpenF1 laps, stints, pit data, race control and intervals are used when the race session is on disk (2023 onward), provided that at least max(3, half of the session's car numbers) map to drivers. Otherwise the model uses the season store's Jolpica lap times and pit stops.</p>\n<span class=\"src\">models/laptime.py</span>\n<h3>Equation</h3>\n<p>For driver i in team t on lap L, on compound c with tyres of age a:</p>\n<div class=\"eq\">lap_{i,L} = team_t + dev_i + fuel · F_{i,L} + off_c + (g_c + tdeg_{t,c} + ddeg_{i,c}) · a + e2 · P2(u_L) + e3 · P3(u_L) + k · traffic_{i,L} + ε_{i,L}</div>\n<ul>\n<li>team_t is the car's level and dev_i is the driver's deviation from it. Their sum is the driver's pace.</li>\n<li>F is the number of laps of fuel on board. Since 2010 it is the laps remaining, N − L. In the refuelling era (1994 to 2009) it is the laps to the driver's next stop, or to the flag.</li>\n<li>off_c is the compound offset relative to the most-used compound, which is the baseline with offset 0. g_c is the compound's linear degradation per lap of tyre age. tdeg is the team's deviation from that slope and ddeg is the driver's deviation from his team's.</li>\n<li>u_L maps laps 1..N onto [−1, 1] as u = 2(L − 1)/(N − 1) − 1. P2(u) = (3u² − 1)/2 and P3(u) = (5u³ − 3u)/2 are Legendre polynomials and capture the non-linear part of track evolution. The linear part of track evolution cannot be separated from fuel burn, since both are linear in L, so the fuel coefficient reports the net linear lap trend. In the refuelling era fuel is not linear in L, so a linear P1(u) = u evolution term is added.</li>\n<li>Tyre age a is OpenF1's tyre_age_at_start plus laps into the stint (2023 onward). Before that, a is laps since the last pit stop, all laps share one compound labelled \"UNKNOWN\", and new tyres are assumed at every stop. OpenF1 compounds recorded as NONE, empty or TEST_UNKNOWN are also treated as UNKNOWN.</li>\n<li>traffic_{i,L} = max(0, 1 − interval/1.5 s), where interval is the gap to the car ahead at the end of lap L − 1 (from OpenF1 lap_end). It is 0 when the car is clear and 1 when it is right behind another car. k is the full cost of running directly behind another car. This term is used only when OpenF1 intervals exist and at least one lap has nonzero traffic.</li>\n</ul>\n<span class=\"src\">models/laptime.py</span>\n<h3>Priors (ridge penalties)</h3>\n<p>Every coefficient has a Gaussian prior. The prior mean is 0 for every coefficient except fuel. A fuel prior mean of 0.06 s per lap of fuel corresponds to about 1.7 kg per lap at about 0.035 s per kg. Within a stint, fuel burn and tyre wear are both linear in the lap number, so fuel is identified only by the level change at pit stops and by drivers stopping on different laps. When those are few, the prior holds the fuel estimate steady. Because dev, tdeg and ddeg are shrunk, a driver with few clean laps is pulled toward his team-mate and the compound mean.</p>\n<table class=\"tbl\"><thead><tr><th>Term</th><th>Prior mean</th><th>Prior sd</th></tr></thead><tbody>\n<tr><td>team intercept</td><td>0</td><td>100 s (effectively free)</td></tr>\n<tr><td>dev (driver relative to team)</td><td>0</td><td>0.5 s</td></tr>\n<tr><td>fuel</td><td>0.06 s per lap of fuel</td><td>0.05</td></tr>\n<tr><td>compound offset</td><td>0</td><td>10 s</td></tr>\n<tr><td>compound degradation g</td><td>0</td><td>1.0 s/lap</td></tr>\n<tr><td>team degradation deviation tdeg</td><td>0</td><td>0.03 s/lap</td></tr>\n<tr><td>driver degradation deviation ddeg</td><td>0</td><td>0.02 s/lap</td></tr>\n<tr><td>traffic k</td><td>0</td><td>10 s</td></tr>\n<tr><td>track evolution (P2, P3, P1)</td><td>0</td><td>0.5 s</td></tr>\n</tbody></table>\n<span class=\"src\">models/laptime.py</span>\n<h3>Clean-lap exclusions</h3>\n<p>Each lap gets at most one exclusion reason. The checks are applied in this order:</p>\n<ul>\n<li>missing: no lap time.</li>\n<li>lap1: the opening lap.</li>\n<li>pit: the in-lap (the lap of the stop) or the out-lap after it. In-laps come from the Jolpica pit-stop table and the OpenF1 pit table. They are also inferred from OpenF1 pit_out flags (the lap before a pit-out lap) and from stint boundaries (the lap before the start of any stint after the first). With no pit data at all, which is the case before 2011, any green lap slower than 110% of the driver's own median green lap is treated as an in-lap, provided the driver has at least 5 such laps.</li>\n<li>neutralised, from three sources:\n <ul>\n <li>A field-median rule used in every season: a lap whose median time across at least 3 cars is more than 107% of the race's median lap is neutralised, and so is the lap after a neutralised block (the restart).</li>\n <li>OpenF1 race-control windows (2023 onward). Any lap whose time span overlaps a window is excluded. An SC window runs from \"SAFETY CAR DEPLOYED\" to \"SAFETY CAR IN THIS LAP\", ENDING or ENDED, plus 1.5 reference laps. A VSC window runs from \"VSC DEPLOYED\" to \"VSC ENDING\", plus 20 s. A red-flag window runs from flag RED, a \"RED FLAG\" message, or a SessionStatus \"ABORTED\" or \"SUSPENDED\" message, until a track-wide GREEN flag or a SessionStatus \"STARTED\" or \"RESUMED\" message, plus one reference lap.</li>\n <li>A window that race control never closes ends at the leader's start of the first green lap after it. If there is no such lap, it ends 5 reference laps after it opened.</li>\n </ul>\n Without lap start times (Jolpica laps) and without windows, the laps that race control spans are used instead.</li>\n<li>outlier: any remaining lap outside [93%, 110%] of the median clean lap.</li>\n</ul>\n<span class=\"src\">models/laptime.py</span>\n<h3>Fit</h3>\n<p>At least 10 clean laps are needed, or the race returns no pace with a reason. The model is fitted by ridge-regularised weighted least squares with Huber IRLS weights:</p>\n<div class=\"eq\">β = (XᵀWX + Λ)⁻¹ (XᵀWy + Λ μ₀),   Λ = diag(σ² / prior_sd²)</div>\n<p>The fit starts from σ = 0.5 s and unit weights. Each iteration does three things:</p>\n<ul>\n<li>It solves for β.</li>\n<li>It sets σ to the robust scale of the residuals, 1.4826 × the median absolute deviation, with a floor of 0.02 s.</li>\n<li>It sets each lap's weight to 1 if |r|/σ ≤ 1.345, and to 1.345/(|r|/σ) otherwise.</li>\n</ul>\n<p>The iteration runs for at most 15 rounds and stops early when the weights change by less than 1e-4 and σ by less than 1e-4. Laps with final weight below 0.5 are counted as down-weighted.</p>\n<span class=\"src\">models/laptime.py</span>\n<h3>Standard errors</h3>\n<p>The residual variance is σ² = Σ w r² / (Σ w − p), where p is the number of coefficients, capped so the denominator stays at least 1. The posterior covariance is σ² (XᵀWX + Λ)⁻¹. Consecutive clean laps of the same driver have correlated residuals. Their lag-1 correlation ρ is estimated when there are more than 10 such pairs and clipped to [0, 0.6], and the covariance is multiplied by (1 + ρ)/(1 − ρ).</p>\n<p>Pace is the contrast pace_i = (team_t + dev_i) − mean over drivers of (team + dev), and its standard error comes from the same contrast applied to the covariance. A driver's degradation on compound c is g_c + tdeg_{t,c} + ddeg_{i,c}, in s per lap of tyre age. traffic_cost is k multiplied by the sum of the traffic values over the driver's clean laps. pace_pct is 100 × pace divided by the median clean lap.</p>\n<p>The output also reports the fuel coefficient (described as \"s per lap of fuel on board, net of linear track evolution\"), compound offsets and slopes, the track-evolution coefficients, σ, ρ, the counts of laps excluded for each reason, and the neutralised laps. Results are cached under a hash of the inputs and the model version.</p>\n<span class=\"src\">models/laptime.py</span>\n</section>\n\n<section id=\"m-decomposition\">\n<h2>Car and driver decomposition</h2>\n<p>Across a season, each race's pace and each qualifying session's pace is split into a car effect, which follows a random walk from round to round for each constructor, and a driver effect, which is fixed for the season. Both are measured in percent of lap time against the field average, and a negative value means faster.</p>\n<h3>Model</h3>\n<div class=\"eq\">y_{i,r} = car_{t,r} + u_{t,r} + drv_i + e_{i,r},   e_{i,r} ~ N(0, se_{i,r}² + τ²),   u_{t,r} ~ N(0, κ²)</div>\n<div class=\"eq\">car_{t,r} = car_{t,r'} + η,   η ~ N(0, q² · (r − r'))   (r' = the previous modelled round)</div>\n<div class=\"eq\">car_{t,first} ~ N(0, 2²),   drv_i ~ N(0, σ_d²)</div>\n<ul>\n<li>u_{t,r} is the car's fit to this circuit, shared by the team-mates and gone by the next round. Without it every circuit-specific swing reads as a step of the random walk and the latest car state follows the last race. The walk's step q is fixed at 0.06% per round for race pace and 0.07% for qualifying rather than fitted per season: predicting each next round's pace from the rounds before it (2012–2026), the team-round term and the fixed step both lowered the Gaussian log-loss in every season.</li>\n<li>For races, y = 100 × race pace / reference lap, with the lap-time model's standard error converted the same way.</li>\n<li>For qualifying, each driver's Q1, Q2 and Q3 times are converted to percentage gaps to the fastest time in that segment. Times more than 105% of the segment's best are dropped. The model gap_{i,s} = a_i + b_s is solved by least squares, with segment offset b fixed at 0 for Q1. Comparing within a segment absorbs track evolution. a_i is then centred on the field mean, and se = 0.10% / √(number of segments the driver ran).</li>\n<li>Team-mates share car_{t,r}, so drv_i is identified from the difference within a team. A driver who changes team mid-season is linked to both cars through his single drv_i. Because drv is shrunk toward 0, two team-mates who are equally fast both get drv = 0 and the car carries their common level.</li>\n</ul>\n<span class=\"src\">models/decomposition.py</span>\n<h3>Estimation</h3>\n<p>The model is linear and Gaussian, so the joint posterior of every car state and every driver effect is computed exactly. Generalised least squares runs on the stacked state vector, with the random-walk prior entered as a banded precision matrix. This gives the same answer as a Kalman smoother. The hyperparameters q, σ_d and τ maximise the marginal likelihood of y plus a weak log-normal hyperprior on each, with log-sd 0.7. The optimiser is L-BFGS-B on log values, with bounds q in [0.005, 2] and σ_d and τ in [0.005, 3]. A season with fewer than 4 observations returns no fit.</p>\n<table class=\"tbl\"><thead><tr><th>Hyperprior centre</th><th>q (random-walk step, % per round)</th><th>σ_d (driver sd, %)</th><th>τ (extra noise, %)</th></tr></thead><tbody>\n<tr><td>Race</td><td>0.15</td><td>0.20</td><td>0.30</td></tr>\n<tr><td>Qualifying</td><td>0.10</td><td>0.15</td><td>0.15</td></tr>\n</tbody></table>\n<span class=\"src\">models/decomposition.py</span>\n<h3>Car versus driver share of points</h3>\n<p>Each team's points are split between car and drivers by a Shapley decomposition on simulated expected points. At every completed round, each driver's score is car_{t,r} + drv_i plus N(0, τ²) race noise. The car state is taken from the nearest modelled round at or before r. Race effects are used, or qualifying effects when there is no race pace. Finishing orders are simulated (4,000 simulations, seed 7) and scored with the season's points table, which is the most common points value at each position in the season's results, falling back to 25-18-15-12-10-8-6-4-2-1.</p>\n<p>For each team, four worlds are simulated with common random numbers: its own car with its own drivers, an average car (effect 0) with its own drivers, its own car with average drivers, and an average car with average drivers. Every other team is left unchanged. The car contribution is the mean of the two marginal gains from switching the car on, and the driver contribution is defined the same way. The two sum to the team's model points minus the average-team baseline. car_share = |car| / (|car| + |drivers|).</p>\n<span class=\"src\">models/decomposition.py</span>\n</section>\n\n<section id=\"m-qualifying\">\n<h2>Qualifying model</h2>\n<p>The pre-qualifying forecast uses the qualifying decomposition fitted through the previous round. It uses no information from the session itself.</p>\n<div class=\"eq\">pace_i = car_t + drv_i + ε_i</div>\n<div class=\"eq\">car_t ~ N(car_{t,R'}, se_{t,R'}² + q² · (R − R')),   drv_i ~ N(drv̂_i, se_i²),   ε_i ~ N(0, τ²)</div>\n<ul>\n<li>The car state is carried forward from the last modelled round R' before R, with the random-walk variance added for each round that has passed. q and τ come from the same fit.</li>\n<li>Team-mates share one car draw per simulation, so their outcomes are correlated.</li>\n<li>A driver without a season effect (a debutant or substitute) gets drv ~ N(0, σ_d²), using the fit's σ_d (0.15 if the fit has none). A team without a car effect gets car ~ N(0, 1²). When the fit has no τ, 0.15 is used, and when it has no q, 0.1.</li>\n<li>At round 1, or whenever the current season has no qualifying effects yet, the previous season's final states are carried over. The extra winter variance is 1.0² (% of lap) on every car and 0.1² on every driver.</li>\n<li>There is no adjustment for circuit type. The store has no lap length, so average lap speed is not available for every season. Car effects are assumed to carry across circuit types, and the random-walk step q absorbs the swings from one circuit to the next.</li>\n</ul>\n<p>The Monte Carlo draws every driver's pace n_sims times (20,000 by default, seed 11) and sorts each draw to get the qualifying classification before grid penalties. p_pole = P(rank 1), grid_dist[k] = P(rank k + 1), mu_gap_pct is the mean gap to the fastest driver in the same draw, exp_grid is the expected rank, and sd = √(car var + driver var + τ²). The race simulator calls this model with 4,000 simulations.</p>\n<span class=\"src\">models/qualifying.py</span><span class=\"src\">models/race_sim.py</span>\n</section>\n\n<section id=\"m-circuits\">\n<h2>Circuit profiles</h2>\n<p>Circuit parameters are learned from history and shrunk toward a global mean according to sample size. Each race since 1996 produces one record, built from Jolpica results, pit stops, lap times and lap-end positions, plus OpenF1 race sessions from 2023 (pit-lane times, race control, rainfall, overtakes, lap times). An OpenF1 race session is matched to a race by date, trying offsets of 0, −1, +1 and −2 days. A profile for a race uses only records strictly before that race, so the backtest never sees the race it predicts.</p>\n<span class=\"src\">models/circuits.py</span>\n<h3>Recency weighting and shrinkage</h3>\n<p>Every record has weight w = 0.5^((Y − y)/4), where Y is the cutoff season and y the record's season (a 4-year half-life). All sums below are weighted, so every n is an effective count. The global profile is the weighted aggregate over all circuits, shrunk toward fixed priors. A circuit's profile is its own records shrunk toward the global profile. The basic estimator is:</p>\n<div class=\"eq\">estimate = (Σ w·x + k·g) / (Σ w + k)</div>\n<table class=\"tbl\"><thead><tr><th>Quantity</th><th>Global prior g (no history)</th><th>Shrinkage k</th></tr></thead><tbody>\n<tr><td>Race laps</td><td>57</td><td>none: the winner's laps at the most recent race there</td></tr>\n<tr><td>Pit loss</td><td>22.0 s</td><td>2 races</td></tr>\n<tr><td>SC hazard per lap</td><td>0.011</td><td>150 laps of exposure</td></tr>\n<tr><td>VSC hazard per lap</td><td>0.006</td><td>150 laps</td></tr>\n<tr><td>Pass probability per opportunity</td><td>0.18</td><td>40 opportunities</td></tr>\n<tr><td>Mean pace delta of an opportunity</td><td>0.6 s</td><td>40 opportunities</td></tr>\n<tr><td>Typical stops per finisher</td><td>1.6</td><td>2 races</td></tr>\n<tr><td>Wet probability</td><td>0.12</td><td>2 races</td></tr>\n<tr><td>Mechanical DNF per starter per race</td><td>0.040</td><td>global 40 starts; circuit multiplier 5</td></tr>\n<tr><td>Incident DNF per starter per race</td><td>0.035</td><td>global 40 starts; circuit multiplier 5</td></tr>\n<tr><td>Lap-1 incident per starter</td><td>0.012</td><td>pooled 50 starts; per grid slot 20; circuit multiplier 5</td></tr>\n<tr><td>Mechanical share of unknown retirements</td><td>0.53</td><td>20 retirements</td></tr>\n<tr><td>SC share of neutralisations</td><td>0.65</td><td>5 events</td></tr>\n<tr><td>Passes per car-lap</td><td>0.05</td><td>2,000 car-laps</td></tr>\n<tr><td>First-lap position change, by slot</td><td>mean 0, sd 1.2 + 0.05 × slot</td><td>30 starts per slot; circuit sd scale 3</td></tr>\n</tbody></table>\n<span class=\"src\">models/circuits.py</span>\n<h3>Laps and distance</h3>\n<p>The data has no lap length. It is approximated as length_km = 305 / laps, using the FIA minimum race distance, or 260.3 / laps at Monaco. Sprint laps = ceil(100 / length_km).</p>\n<h3>Pit loss</h3>\n<p>For each stop, loss = (in-lap + out-lap) − 2 × ref. Here ref is the driver's median green lap over laps l − 4 to l + 5, excluding the in-lap and out-lap. Stops with a loss outside 8 to 45 s are dropped as affected by a safety car, and the race value is the median over the remaining stops. Before 2011 there is no pit-stop table, so a stop is detected on a green lap when lap_l + lap_{l+1} − 2 × ref exceeds 12 s and the in-lap alone exceeds ref by more than 3 s. OpenF1 pit-lane times between 10 and 60 s are kept as pit_lane_s, and they become the race's pit loss when no lap times exist.</p>\n<h3>Safety car and VSC hazards</h3>\n<p>These are Gamma-Poisson estimates per green lap of exposure:</p>\n<div class=\"eq\">rate = (events_w + 150 · g) / (exposure_laps_w + 150)</div>\n<p>From 2023 the events are counted from OpenF1 race control: \"SAFETY CAR DEPLOYED\", \"VIRTUAL SAFETY CAR DEPLOYED\", and red flags, each red flag counting as half an SC event. Before 2023, neutralised laps are detected statistically: a lap whose field-median time exceeds 1.20 × the race's median green lap is neutralised. Each run of consecutive neutralised laps after lap 1 is one event. Events are split between SC and VSC by the OpenF1-era share, which is shrunk toward 0.65 with 5 pseudo-events. Every event before 2015, before the VSC existed, counts as an SC. Exposure is the race's laps minus one. The profile reports p_sc_race = 1 − exp(−rate × laps), and the same for the VSC.</p>\n<h3>Overtaking</h3>\n<p>An opportunity exists when a car meets all of these conditions:</p>\n<ul>\n<li>At the end of lap k − 1 it is directly behind another car, within 1.5 s by cumulative time.</li>\n<li>The median of its previous 3 laps is at least 0.3 s faster than the car ahead's.</li>\n<li>Both laps are green: no pit in-lap or out-lap for either car, and neither lap is neutralised.</li>\n<li>The lap is the fifth lap or later.</li>\n</ul>\n<p>The opportunity succeeds when the car is ahead at the end of lap k. pass_prob = (successes_w + 40 × g) / (opportunities_w + 40). The race simulator passes with probability sigmoid((Δpace − thr) / 0.25 s). The threshold is set so that a typical opportunity, at the mean pace delta d̄, passes at the observed rate:</p>\n<div class=\"eq\">thr = d̄ − 0.25 · logit(pass_prob),   clipped to [0.2, 2.5] s</div>\n<div class=\"eq\">overtake_difficulty = clip(1 − pass_prob / (2 · g_pass), 0.02, 0.98)   (0.5 = an average circuit)</div>\n<p>On-track position swaps per green car-lap are also reported as passes_per_car_lap. A swap is a pair changing order with neither car pitting, and OpenF1 overtakes are added from 2023, normalised by starters × laps.</p>\n<h3>Strategy</h3>\n<p>The typical stop count is the mean number of stops per classified finisher, shrunk toward 1.6 with k = 2 and clipped to [1, 3].</p>\n<h3>First lap</h3>\n<p>For each driver, the first-lap delta is his position at the end of lap 1 minus his grid slot, for slots 1 to 26. Pit-lane starters and slots above 26 count as slot 26. For the global profile, each slot's mean and variance are shrunk toward the prior (mean 0, sd 1.2 + 0.05 × slot) with 30 starts, and the sd is floored at 0.5. A circuit keeps the global means and scales the global sds by a factor. The factor is the weighted mean, over the circuit's races, of √(Σ δ² / Σ global sd²), shrunk toward 1 with k = 3.</p>\n<h3>Classification and DNF split</h3>\n<p>Each result row is classified as follows:</p>\n<ul>\n<li>A row with a numeric position_text is classified. This includes drivers recorded as \"Retired\" but classified on distance.</li>\n<li>W, F or a did-not-start status means the driver did not start.</li>\n<li>D or E means disqualified.</li>\n<li>Every other row is a DNF.</li>\n</ul>\n<p>DNF statuses are split by keyword into mechanical (engine, gearbox, hydraulics, power unit, and so on), incident (accident, collision, spun, damage, puncture, and so on) and unknown (for example \"Retired\"). Unknown DNFs are split using the global mechanical share. Global DNF rates are the weighted mean, shrunk toward the priors with 40 pseudo-starts. A circuit has multipliers m = (obs_w + 5) / (exp_w + 5), where exp_w is the global rate times the circuit's weighted starters, so a circuit needs several excess retirements before its multiplier moves away from 1.</p>\n<p>The lap-1 incident probability by grid slot counts retirements with 0 laps completed. It is (k_g + 20 × p) / (n_g + 20), centred on the pooled rate p, and the pooled rate itself is shrunk with 50 starts toward 0.012. A circuit scales the slot table by a multiplier with k = 5.</p>\n<h3>Wet chance</h3>\n<p>A race counts as wet when any OpenF1 weather sample during the race reports rainfall. p_wet = (wet_w + 2 × 0.12) / (n_w + 2). This information exists only from 2023.</p>\n<span class=\"src\">models/circuits.py</span>\n</section>\n\n<section id=\"m-race-sim\">\n<h2>Race simulator</h2>\n<p>The race simulator is a vectorised, lap-by-lap Monte Carlo that runs n races at once (20,000 by default). The race forecasts on the site come from it. It is a full model of every lap, not an approximation at the level of stints.</p>\n<span class=\"src\">models/race_sim.py</span>\n<h3>Inputs</h3>\n<p>Every input is built from data strictly before the race, except that the post-qualifying forecast also uses the race's own grid. The entry list is the race's qualifying or results rows, or, for a future race, the lineup from the latest completed round.</p>\n<p>Results-only pace estimator. Every earlier race, qualifying and sprint result from the current and two previous seasons becomes a normal score:</p>\n<div class=\"eq\">z = Φ⁻¹((rank − 0.5) / N)</div>\n<p>For races and sprints, rank is the position among classified finishers and N is the number of starters. For qualifying, rank is the position and N the number of entries. Each observation has weight</p>\n<div class=\"eq\">w = kind · season · 0.5^(races_ago / 6)</div>\n<p>where kind is 1.0 for a race, 0.8 for qualifying and 0.5 for a sprint, and races_ago is counted across seasons. The season factor is 1 for the current season, 0.35 for the previous season and 0.12 for two seasons back. In a season that follows a regulation reset (2014, 2017, 2022, 2026), the previous seasons count 0.08 and 0.03 instead. Scores are then shrunk:</p>\n<div class=\"eq\">z_team = (Σ_team w z + 1 · 0.5) / (Σ_team w + 1)   (race and sprint observations; 0.5 = a new team's prior)</div>\n<div class=\"eq\">z_d = (Σ w z + 2 · z_team) / (Σ w + 2)</div>\n<div class=\"eq\">μ_d = 0.90 · z_d % of lap,   sd_d = 0.90 · 0.7 / √(Σ w + 2)</div>\n<p>The pace scale of 0.90% of the lap per unit of z (about 0.8 s on a 90 s lap) was chosen by walk-forward winner log-loss over 2014–2026. Pace is converted to s/lap with the circuit's reference lap: its latest race's median green lap. The qualifying strength used to sample a grid comes from the same estimator on qualifying results only, shrunk toward z_d with weight 2.</p>\n<p>Blend with the lap-time decomposition. When the decomposition is available, its race pace through the latest completed round is used. Pace is the latest car effect plus the driver effect, in % of lap (converted to s/lap with the circuit's reference lap, like the results-only estimate), and se = √(se_car² + se_drv²). It is blended with the results-only estimate:</p>\n<div class=\"eq\">μ = w_A · μ_A + (1 − w_A) · μ_results,   sd² = w_A · sd_A² + (1 − w_A) · sd_results²,   w_A = n / (n + 40)</div>\n<p>Here n is the number of rounds with observed race pace. The constant 40 was chosen by walk-forward winner log-loss over 2014–2026 (the same choice in every season): lap-time pace from a handful of rounds carries less about the next result than the results themselves, so it earns half the weight only after 40 rounds. The blend is used only if the decomposition covers at least 80% of the field. Drivers it does not cover get the slowest covered pace plus 0.3 s, with sd 0.4.</p>\n<p>Grid. After qualifying, the actual grid is used, and pit-lane starters go behind everyone. Before qualifying, each simulation draws each driver's slot independently from the qualifying model's grid distribution, adds uniform jitter, and ranks the results. If that distribution is unavailable, the grid is sampled as z_q + 0.55 · ε and ranked.</p>\n<p>Retirement hazard. Mechanical risk is estimated per team and incident risk per driver, using the same observation weights and excluding lap-1 retirements:</p>\n<div class=\"eq\">p_m = (Σ w·mech + 8 · g_m) / (Σ w·starts + 8) · circuit mechanical multiplier</div>\n<div class=\"eq\">p_i = (Σ w·incident + 12 · g_i) / (Σ w·starts + 12) · circuit incident multiplier</div>\n<div class=\"eq\">h = −ln(1 − min(0.6, p_m + p_i)) / laps</div>\n<p>g_m is the global mechanical rate. g_i is the global incident rate minus the mean lap-1 incident rate, floored at 0.005. Unknown statuses are split using the mechanical share.</p>\n<span class=\"src\">models/race_sim.py</span>\n<h3>Simulation steps</h3>\n<ul>\n<li>Race-day pace. x_d = μ_d + sd_d · e1 + c_team · e2 + c_drv · e3, with a team-shared day sd c_team = 0.16 s/lap and a driver day sd c_drv = 0.10 s/lap. Championship runs add season offsets here (see the next section).</li>\n<li>Lap 1. score = slot + m[slot] + 0.4 · s[slot] · k_c · e + B · Exponential(8) − 1.0 · (x_d − median x), with B = 1 for 10% of cars. Here m and s are the circuit's first-lap mean and sd by slot and k_c is its sd scale. The observed sd includes the occasional car that loses many places, and ranking noisy scores moves a car by its neighbours' noise as well as its own, so the full Gaussian spread let the pole-sitter lead after lap 1 in 34% of simulations against 72% of races (2014–2025). A narrow core plus a tail of bad starts, fitted to how often each slot keeps its place, loses three or more and gains two or more, fixes that. Ranking the scores gives the lap-1 order, and cars complete the lap 0.65 s apart plus up to 0.05 s of uniform jitter. Each car retires on lap 1 with its slot's lap-1 incident probability, capped at 0.5.</li>\n<li>Lap time. t = x_d + deg · age + 0.06 · (L − lap) + 0.35 · e. The degradation deg is 0.06 s per lap of tyre age unless one is supplied. The fuel term, 0.06 s per lap of fuel remaining, is common to all cars. The circuit's reference lap is added. These seconds, like the day-to-day sds, are stated for a 90 s lap and scale with the circuit's reference lap.</li>\n<li>Strategy. The race's number of stops is k = 1 + Binomial(2, (m − 1)/2), drawn once per simulated race, so its mean equals the circuit's typical stops m (clipped to [1, 3], at most 3 stops); each car departs from it by one stop with probability 0.1. In 2011–2025 the winner and runner-up made different numbers of stops in 19% of races; drawing every car's count independently made 58% of pairs differ and turned clear favourites into coin flips. Stop j comes on lap L · j/(k + 1) + N(0, 0.07 L), rounded and clipped to [2, L − 1]. A stop costs the pit loss + N(0, 0.6) s, and with probability 0.03 a slow stop adds a uniform 4 to 8 s. Under an SC a stop costs 0.5 × pit loss, and under a VSC 0.65 ×. During any neutralisation, planned stops in the next 6 laps are brought forward to the current lap (32% of cars pit under a simulated safety car, against 34% in the 2023–2025 pit records). Sprints have no stops. A fixed number of stops can be given per driver.</li>\n<li>Overtaking. Cars are processed front to back in the previous lap's order. A car that would finish the lap within 0.4 s of the nearest car ahead that is not pitting, or ahead of it, must pass it. The pass succeeds with probability sigmoid((Δpace − thr)/0.25), where Δpace is the difference in underlying pace without lap noise and thr is the circuit's overtake threshold. A successful pass puts the car 0.1 s ahead. A failed pass leaves it 0.4 s behind. No passing is allowed under an SC or VSC. As an approximation, each car is checked only against the nearest car ahead, so a much faster car can clear two cars in one lap.</li>\n<li>SC and VSC. On each green lap an SC starts with probability sc_rate (three times as likely on lap 1) and lasts 3 to 5 laps. Otherwise a VSC starts with probability vsc_rate (also tripled on lap 1) and lasts 2 to 3 laps. When an SC starts, the gaps reset to 0.8 s per position. Neutralised laps take 1.4 × and 1.3 × the reference lap under an SC and a VSC for every car.</li>\n<li>Retirement after lap 1. Each car's retirement lap is drawn once as 1 + Geometric(1 − e^(−h)). A car is classified if it completes at least 90% of the laps (ceil(0.9 L)). DNF means not classified.</li>\n<li>Wet races. All simulations are wet when the race is marked wet. Otherwise each simulation is wet with the circuit's p_wet. A wet simulation multiplies the day sd by 1.6, the lap noise by 2, the SC and VSC hazards by 2.5, the retirement hazard by 1.8 and the lap-1 spread by 1.3.</li>\n<li>Finishing order. Running cars are ordered by total time. Retired cars come after them, ordered by laps completed, with ties broken at random.</li>\n</ul>\n<span class=\"src\">models/race_sim.py</span>\n<h3>Points</h3>\n<table class=\"tbl\"><thead><tr><th>Seasons</th><th>Race points (P1 onward)</th><th>Sprint points</th></tr></thead><tbody>\n<tr><td>2010 onward</td><td>25, 18, 15, 12, 10, 8, 6, 4, 2, 1</td><td>2021: 3, 2, 1; 2022 onward: 8, 7, 6, 5, 4, 3, 2, 1</td></tr>\n<tr><td>2003 to 2009</td><td>10, 8, 6, 5, 4, 3, 2, 1</td><td>none</td></tr>\n<tr><td>1991 to 2002</td><td>10, 6, 4, 3, 2, 1</td><td>none</td></tr>\n<tr><td>before 1991</td><td>9, 6, 4, 3, 2, 1 (a simplification)</td><td>none</td></tr>\n</tbody></table>\n<p>By rule, the fastest-lap bonus point applies from 2019 to 2024. The rule is then checked against the season's own results. If at least 2 classified top-10 drivers with fastest-lap rank 1 have exactly one point more than their position's value, and these outnumber the opposite case, the season had the bonus. If at least 3 have exactly the position's value and none has the extra point, it did not. In a simulation, the fastest lap goes to the running car with the best x_d + N(0, 0.3), and it earns the point only if that car finishes classified in the top 10. Points go to classified cars only.</p>\n<p>Each driver's outputs are p_win, p_podium, p_points (classified within the points-paying positions), p_dnf, exp_pos, exp_points and the full position distribution. Each team gets exp_points and p_double_points. Each race also reports p_sc, p_vsc and p_wet. Simulating 20,000 races of 22 cars over 57 laps takes about 2.5 s.</p>\n<span class=\"src\">models/race_sim.py</span>\n</section>\n\n<section id=\"m-championship\">\n<h2>Championship simulation</h2>\n<p>The current points total is summed from the store's results and sprint rows exactly as they were awarded. A constructor's total is the sum over its rows, so a driver who changed team scores for each team in turn. Every calendar round without results is simulated with the race simulator, and a round that has a sprint session but no sprint results gets a sprint first. A round whose qualifying, or sprint grid, is already in the store uses the actual grid. The default is n = 20,000 season simulations.</p>\n<span class=\"src\">models/championship.py</span>\n<h3>Correlated season draws</h3>\n<p>Within one simulation, every remaining race shares season-level draws, so that a team's season holds together:</p>\n<div class=\"eq\">offset_{s,d,r} = sd_{d,r} · z_{s,d} + F_{s,team(d),r} + G_{s,d,r}</div>\n<ul>\n<li>z ~ N(0, 1) is drawn once per season, so the error in the pace estimate persists across the remaining rounds.</li>\n<li>F is a team random walk, F_r = F_{r−1} + N(0, 0.06) s/lap per round, representing the development race.</li>\n<li>G is a driver random walk with a step of 0.03 s/lap per round.</li>\n</ul>\n<p>Each race then adds its own day-to-day noise inside the race simulator, which does not redraw the parameter uncertainty (draw_param = False). Each race gets its own random seed drawn from the season's generator.</p>\n<h3>Ranking and countback</h3>\n<p>The final order is by points. Ties are broken by Grand Prix wins, then second places, and so on, as in the FIA countback; sprint results do not count. Only classified finishes count. Each simulation encodes this as one integer key: (2 × points) shifted left by places × bits, ORed with the count of each place. Drivers use 10 places at 5 bits each, and constructors use 8 places at 6 bits each, with each count capped to fit its bits. Identical keys are split at random.</p>\n<h3>Outputs</h3>\n<p>For each driver and constructor the simulation reports p_title, expected points, points quantiles (5, 25, 50, 75, 95), the final position distribution, the expected position, and expected points per remaining round.</p>\n<h3>Magic numbers, clinched, eliminated</h3>\n<p>Magic numbers are computed directly, without simulation. R is the most points anyone can still score: per Grand Prix the winner's points plus the fastest-lap point where it is awarded, and per sprint the sprint winner's points. For constructors R uses the top two places in each race and each sprint.</p>\n<div class=\"eq\">magic_d = max over rivals r of (P_r + R) − P_d + 1</div>\n<p>If d scores that many more points, no rival can reach him even by winning everything left. The +1 ignores countback, so the figure is conservative. A driver has clinched when magic ≤ 0 and is eliminated when P_d + R &lt; the current leader's points. can_clinch_alone is true when magic ≤ R.</p>\n<h3>Conditionals</h3>\n<p>For the points leader (ties broken by p_title), each remaining Grand Prix reports p_win_round, p_title_if_win and p_title_if_not_win. These are the share of simulations in which the leader is champion, among those where he does or does not win that round. The same figures are reported for the next round for every contender with p_title of at least 0.005.</p>\n<span class=\"src\">models/championship.py</span>\n</section>\n\n<section id=\"m-elo\">\n<h2>Elo ratings</h2>\n<p>There are three driver ratings, all on the usual Elo scale (1500 = average; a 400-point gap means 10:1 odds in a head-to-head). All three are updated once per Grand Prix in calendar order from 1950.</p>\n<ul>\n<li>Field Elo rates the finishing order against the whole field. The car dominates that order, so field Elo mostly rates the driver and car together, as an entry.</li>\n<li>Teammate Elo is updated only on head-to-heads against the driver's own team-mates, who had the same car. It is the cleaner driver signal and the basis of the all-time table. It is only as good as the team-mates a driver faced, and ratings move between teams only as drivers change seats.</li>\n<li>Qualifying Elo is field Elo on qualifying positions. Qualifying classifications exist from 1994. Before that, the starting grid stands in, with pit-lane starts dropped.</li>\n</ul>\n<h3>Update</h3>\n<div class=\"eq\">E_ij = 1 / (1 + 10^((R_j − R_i)/400)),   ΔR_i = K/(n − 1) · Σ_{j≠i} w_ij · (S_ij − E_ij)</div>\n<p>n is the number of drivers in the update (weight greater than 0), so one race moves a driver by at most K whatever the field size. Updates are zero-sum. The pair weight is w_ij = min(w_i, w_j), and a pair of two non-classified drivers is skipped.</p>\n<table class=\"tbl\"><thead><tr><th>Constant</th><th>Value</th></tr></thead><tbody>\n<tr><td>K field</td><td>32</td></tr>\n<tr><td>K teammate</td><td>24</td></tr>\n<tr><td>K qualifying</td><td>32</td></tr>\n<tr><td>Initial rating</td><td>1500 (drivers already racing in the first season on disk)</td></tr>\n<tr><td>Rookie offset</td><td>a debutant starts at the mean of the rated drivers in his first race minus 100 (each rating separately)</td></tr>\n<tr><td>Season regression</td><td>R ← 1500 + (1 − 0.15)(R − 1500), applied to all three ratings before each season</td></tr>\n<tr><td>Peak eligibility</td><td>peaks count from a driver's 20th start</td></tr>\n<tr><td>All-time table</td><td>at least 50 career starts, ranked by peak teammate Elo</td></tr>\n<tr><td>Ambiguous retirement weight</td><td>0.5</td></tr>\n</tbody></table>\n<h3>Retirements</h3>\n<table class=\"tbl\"><thead><tr><th>Class</th><th>Rule</th><th>Weight</th></tr></thead><tbody>\n<tr><td>finished</td><td>numeric position_text, or status Finished, Lapped or +n Laps</td><td>1.0, at their position</td></tr>\n<tr><td>driver-caused</td><td>accident, collision, spun off, crash</td><td>1.0, behind all classified</td></tr>\n<tr><td>mechanical</td><td>engine, gearbox, hydraulics, power unit, brakes, electrical, and many more</td><td>0 (rating untouched)</td></tr>\n<tr><td>ambiguous</td><td>\"Retired\", \"Not classified\", \"Damage\", unknown reasons</td><td>0.5, behind all classified</td></tr>\n<tr><td>excluded</td><td>did not start, qualify or prequalify; withdrew; disqualified; excluded; injury or illness</td><td>0 (not in the update)</td></tr>\n</tbody></table>\n<p>Jolpica no longer publishes detailed retirement reasons in recent seasons, so modern retirements are all ambiguous and cost half as much as a crash.</p>\n<h3>Teammate head-to-heads</h3>\n<p>Within each constructor's entries in a race, a pair counts only when both drivers were classified, or when one was classified and the other retired for a driver-caused reason (the classified driver wins). Mechanical and ambiguous retirements and non-starts produce no head-to-head. The update is ΔR_i = K_teammate/(m − 1) · Σ (S − E) over the m drivers of that team who appear in an eligible pair.</p>\n<h3>Other rules</h3>\n<p>Sprints are not rated. The Indianapolis 500, a championship round from 1950 to 1960 with an almost entirely separate field, is skipped. A driver with two cars in one race, as happened with shared drives in the 1950s, is rated on his best-placed entry. Forecasts use each driver's latest post-race ratings strictly before the race, without the season regression.</p>\n<span class=\"src\">models/elo.py</span>\n</section>\n\n<section id=\"m-plackett-luce\">\n<h2>Plackett-Luce ranking model</h2>\n<p>The Plackett-Luce model reads a finishing order as successive draws without replacement. The winner is drawn from the whole field with probability proportional to exp(θ_i), second place from those left, and so on. For an observed order o_1..o_k, which may cover only the top k, from a field F:</p>\n<div class=\"eq\">P(o | θ) = Π_{s=1..k} exp(θ_{o_s}) / Σ_{j ∈ R_s} exp(θ_j),   R_s = F minus {o_1..o_{s−1}}</div>\n<p>Competitors in the field but missing from the observed order are known only to finish behind o_k, so they stay in every denominator. The last remaining competitor carries no information. The fit maximises the penalised log-likelihood</p>\n<div class=\"eq\">L(θ) = Σ_orders w_o · log P(o | θ) − (ridge/2) · Σ θ_i²</div>\n<p>with L-BFGS on the analytic gradient, starting from 0, for at most 500 iterations. The default ridge is 0.1, which is a Gaussian prior θ ~ N(0, 1/ridge). The ridge makes the problem identifiable and keeps a competitor who always wins or always loses at a finite strength. The fitted θ are centred to mean 0. P(win) is exactly softmax(θ). Top-k probabilities and expected position are estimated by sampling orders with the Gumbel trick: the argsort of θ_i + G_i, with G_i ~ Gumbel(0, 1) independent, is an exact Plackett-Luce draw.</p>\n<span class=\"src\">common/ranking.py</span>\n<p>In F1 the model serves as a benchmark in the backtest. It is fitted on classified finishing orders from the current and two previous seasons, with weights 1, 0.35 and 0.12, and the rest of each race's starters placed behind. A driver without a fitted strength gets the field minimum minus 0.5. The DNF probability is the base rate.</p>\n<span class=\"src\">models/backtest.py</span>\n</section>\n\n<section id=\"m-markets\">\n<h2>Markets</h2>\n<p>Prices come from Kalshi and Polymarket and are mapped to Jolpica driverIds and constructorIds. Kalshi series used: KXF1 (drivers' champion), KXF1CONSTRUCTORS (constructors' champion), KXF1RACE (race winner) and KXF1H2H (driver matchups). Polymarket events used: the drivers' champion event (tried as the year-specific slug first, then the generic one), the constructors' champion event, the race-winner events tagged \"f1\", head-to-head events, and season \"finish ahead of\" markets.</p>\n<span class=\"src\">sources/markets.py</span>\n<h3>Prices</h3>\n<p>A price is the midpoint (bid + ask)/2 of a live two-sided quote. It is accepted only when 0 &lt; bid ≤ ask &lt; 1 and ask − bid ≤ 0.12. A last-traded price is never used as a price.</p>\n<span class=\"src\">football/sources/prediction_markets.py</span>\n<h3>Consensus and de-vig</h3>\n<p>For each runner, the mids from all sources are averaged into one consensus mid, excluding eliminated runners. The field is then de-vigged multiplicatively:</p>\n<div class=\"eq\">p_i = m_i / Σ_j m_j</div>\n<p>Runners at the floor and eliminated runners get probability 0. A market that has settled (a runner resolved Yes) is not published.</p>\n<span class=\"src\">sources/markets.py</span><span class=\"src\">common/markets.py</span>\n<h3>Thin-market rule</h3>\n<p>A field market is published only when two conditions hold:</p>\n<ul>\n<li>At least max(4, half the field) runners are accounted for.</li>\n<li>The implied total of the two-sided mids is between 0.8 and 1.3.</li>\n</ul>\n<p>A runner is accounted for if it meets any of these:</p>\n<ul>\n<li>It has a two-sided quote.</li>\n<li>It is eliminated: a Kalshi market with result \"no\", or a Polymarket runner market closed and settled No. Polymarket closes a title runner's market once that runner is mathematically eliminated.</li>\n<li>It is at the floor: no bid and an ask of at most 0.02.</li>\n</ul>\n<p>Late in a one-sided season, most of the field trades only at \"no bid, 1c ask\". That quote means \"under 1%\", not \"unpriced\", so those runners count toward coverage, but their floor price is never used as a price. Closed Polymarket markets that have not settled are ignored.</p>\n<h3>Race winner and head-to-heads</h3>\n<p>A race-winner event is matched to a round by date, within ±3 days. Polymarket slugs that contain constructor, sprint, pole or practice are excluded. For a head-to-head, a Kalshi pair with both sides quoted is de-vigged as p_a = m_a/(m_a + m_b), and with one side quoted it is that side's mid or one minus it. For Polymarket the first outcome's mid is used. When both sources price a pairing, p_a is their mean.</p>\n<h3>Name mapping</h3>\n<p>Driver labels are tried against an alias table first (for example \"Jr.\" for Sainz and \"Kimi\" for Antonelli), then the three-letter code, then fuzzy matching on full names, then fuzzy matching on unique family names with a match floor of 0.8. Constructor labels are tried against an alias table, then the id itself, then fuzzy matching on names with \"F1 Team\" words stripped. The fuzzy matcher uses a floor of 0.72 by default and gives up when the second-best candidate scores within 0.02 of the best. Unmatched labels are reported, never guessed.</p>\n<span class=\"src\">sources/markets.py</span><span class=\"src\">football/sources/prediction_markets.py</span>\n<h3>Edge</h3>\n<p>Edge is relative, not a difference:</p>\n<div class=\"eq\">edge = model probability / market probability − 1</div>\n<p>A 2-point gap means something very different at 5% than at 50%, which is why the edge is relative.</p>\n<span class=\"src\">common/markets.py</span><span class=\"src\">football/core/markets.py</span>\n</section>\n\n<section id=\"m-backtest\">\n<h2>Backtest</h2>\n<p>The backtest is walk-forward. Every Grand Prix with results in the chosen seasons is predicted using only data strictly before it. The race inputs and the circuit profile are both cut off at the race, and the post-qualifying variant also sees the race's own grid. Four events are scored per driver:</p>\n<ul>\n<li>win;</li>\n<li>podium (top 3);</li>\n<li>points finish (classified in the top 10);</li>\n<li>DNF (not classified).</li>\n</ul>\n<p>Drivers who did not start are dropped. The default seasons are 2023 to 2026. A past season whose results are incomplete on disk is skipped and listed with the reason, and the current season is used to date. Each race is simulated with 4,000 simulations, seeded with seed + 1000 × year + round.</p>\n<span class=\"src\">models/backtest.py</span>\n<h3>Models compared</h3>\n<table class=\"tbl\"><thead><tr><th>Model</th><th>Timing</th><th>Definition</th></tr></thead><tbody>\n<tr><td>model_pre / model_post</td><td>before / after qualifying</td><td>the race simulator, with the decomposition blend where available</td></tr>\n<tr><td>model_pre_results_only</td><td>before qualifying</td><td>the simulator with the results-only pace estimator</td></tr>\n<tr><td>grid_order</td><td>after qualifying</td><td>p = sigmoid(a + b · slot), with a pit-lane start as the last slot. Fitted by maximum likelihood (ridge 1e-3) on all races of previous seasons; earlier rounds of the same season if there are none; defaults if fewer than 3 races. Rescaled so the field's win, podium and points probabilities sum to 1, 3 and 10.</td></tr>\n<tr><td>previous_results</td><td>before qualifying</td><td>the driver's frequency of each event over his last 5 starts, shrunk toward the field base rate with 2 pseudo-starts, rescaled as above</td></tr>\n<tr><td>elo</td><td>before qualifying</td><td>field Elo before the race as Plackett-Luce log-strengths θ = elo · ln(10)/400 (unrated drivers: the mean minus 100). DNF is the base rate.</td></tr>\n<tr><td>plackett_luce</td><td>before qualifying</td><td>Plackett-Luce strengths fitted on earlier finishing orders (see above)</td></tr>\n</tbody></table>\n<p>The DNF base rate comes from up to the last 60 races of previous seasons and is shrunk toward 0.12 with 20 pseudo-starts. Default grid-logistic coefficients (a, b): win (−0.5, −0.45), podium (0.8, −0.35), points (2.6, −0.28), DNF (−2.2, 0.02).</p>\n<h3>Metrics</h3>\n<div class=\"eq\">log-loss = −mean(y ln p + (1 − y) ln(1 − p)),   p clipped to [1e-4, 1 − 1e-4]</div>\n<div class=\"eq\">Brier = mean((p − y)²)</div>\n<p>Log-loss and Brier are computed for each event and each model, overall and per season. The multiclass winner log-loss is −mean(ln p_winner), with win probabilities renormalised to sum to one. Reliability uses 10 equal-width bins, each reporting the mean forecast, the observed frequency and the count. Results are written to <code>data/f1/cache/backtest.json</code>.</p>\n<span class=\"src\">models/backtest.py</span>\n</section>\n\n<section id=\"m-telemetry\">\n<h2>Telemetry processing</h2>\n<p>Raw OpenF1 car data arrives at about 3.7 Hz, timestamped in ms from the session start, and the location feed arrives at about the same rate. Each lap is processed in its window [t_start, t_start + lap_ms] from the session record. A lap needs at least 20 car samples in its window.</p>\n<span class=\"src\">telemetry.py</span>\n<h3>Distance</h3>\n<p>Distance is integrated from speed sample by sample: d += v · dt, with v in m/s. The reference lap is the fastest timed lap of the session that has telemetry, and its integrated distance is the session's lap length. Every other lap is rescaled so that it ends at that length, which keeps laps comparable point by point. A lap whose integrated distance is below 0.8 × or above 1.25 × the reference length is skipped as partial or distorted by the pit lane.</p>\n<h3>Corner detection</h3>\n<p>Corners are found once per session, on the reference lap. A corner is a local minimum of speed whose prominence is at least 25 km/h. Prominence is the rise from the minimum to the lower of the highest speeds within 600 m on either side. A minimum within 150 m of the previous corner replaces that corner if it is slower, and is otherwise ignored. Corners are numbered in order along the lap, each with its distance d and apex speed v. On every lap, the corner minimum is the lowest speed within ±80 m of the reference apex.</p>\n<h3>Braking points</h3>\n<p>For each corner, the braking point is the distance before the apex at which the braking zone into it began. That is the last off-to-on brake transition within the 400 m before the apex, and it is null if there is none.</p>\n<h3>Per-lap summary</h3>\n<p>Time shares are computed from sample durations as a percentage of lap time:</p>\n<ul>\n<li>full throttle: throttle ≥ 98;</li>\n<li>braking: brake &gt; 0;</li>\n<li>coasting: throttle &lt; 2 and no brake.</li>\n</ul>\n<p>Gear changes count the samples where the gear differs from the previous sample. DRS open time is the seconds with a DRS code of 10, 12 or 14.</p>\n<h3>What is stored</h3>\n<p>One file per session is written to <code>docs/paddock/data/&lt;year&gt;/telemetry/&lt;session_key&gt;.json</code>. Drivers in this file are keyed by car number as a string, as in the session record, not by driverId.</p>\n<ul>\n<li><code>ref</code>: driver (car number), lap, length_m, and corners as a list of objects with n, d (m) and v (km/h).</li>\n<li><code>laps</code>: per driver, one row per lap: <code>[lap, top_speed_kph, mean_speed_kph, full_throttle_pct, braking_pct, coasting_pct, gear_changes, drs_open_s]</code>.</li>\n<li><code>corner_min</code>: per driver, per lap (string key), the minimum speed at each corner, in corner order.</li>\n<li><code>brake_points</code>: per driver, per lap, the metres before the apex at which braking began, per corner.</li>\n<li><code>fastest</code>: per driver, the fastest valid lap resampled every 10 m from 0 to the reference length, as <code>{\"d\": 10, \"speed\", \"throttle\", \"brake\", \"gear\", \"rpm\", \"drs\", \"x\", \"y\", \"lap\", \"ms\"}</code>. Each channel is an integer array, one value per 10 m. x and y come from the location feed: the first location sample at or after the interpolated time of each distance point.</li>\n</ul>\n<p>A session is reprocessed when its output is missing or older than its newest raw telemetry file.</p>\n<span class=\"src\">telemetry.py</span><span class=\"src\">scripts/f1_telemetry.py</span>\n</section>\n\n<section id=\"m-metrics\">\n<h2>Driver and team metrics, and awards</h2>\n<p>The driver catalogue for each season groups its metrics as follows: Results, Qualifying, Race pace, Racecraft, Tyres, Reliability, Telemetry style and Points. Each metric has a key, label, group, format, a flag saying whether lower is better, a description and a scope. Each driver gets the value of every metric and two percentiles: one against the field (0 to 100, where 100 is best) and one against his team-mate. Each driver also gets a per-race log of grid, finishing position, status, points, qualifying position, corrected pace and pace rank, positions gained, lap-1 gain, overtakes, pit stops and degradation.</p>\n<p>Team metrics use the same structure. They add pit-stop statistics (median and best stationary time, the share of stops under 2.5 s, and the stop count) and a per-race log of points, car pace, qualifying pace and DNFs. The Lab table holds one row per driver-season with every catalogue metric.</p>\n<p>Each race page lists these awards:</p>\n<ul>\n<li>driver of the day</li>\n<li>best drive from the back</li>\n<li>best strategy</li>\n<li>fastest stop</li>\n<li>overtake of the race</li>\n<li>unluckiest</li>\n<li>smoothest</li>\n<li>team of the weekend</li>\n</ul>\n<p>Each driver award records the driver, a value, a label and a reason. Race pages also show expected against actual finishing position: each driver's expected position and the percentile of his actual result.</p>\n<span class=\"src\">PAYLOADS.md</span>\n</section>\n\n<section id=\"m-limitations\">\n<h2>Limitations</h2>\n<ul>\n<li>2026 regulation reset. Cars and power units changed for 2026, so earlier form says less about the current order. The results-only estimator treats 2026 as a reset season, giving the previous two seasons weights of 0.08 and 0.03 instead of 0.35 and 0.12. The qualifying model's carry-over from the previous season at round 1 adds variance of 1.0² (% of lap) per car and 0.1² per driver. Early-season forecasts are therefore wide.<span class=\"src\">models/race_sim.py</span><span class=\"src\">models/qualifying.py</span></li>\n<li>No tyre compounds before 2023. Jolpica lap times carry no compound or tyre-age information. Before 2023 the lap-time model uses a single \"UNKNOWN\" compound with tyre age counted from the last stop, and stint charts have no compound. Before 2011 there is no pit-stop table, so stops are inferred from slow laps.<span class=\"src\">models/laptime.py</span><span class=\"src\">models/circuits.py</span></li>\n<li>Retirement reasons. From 2023 Jolpica statuses are mostly just \"Retired\" (and \"Lapped\" for classified runners), not the cause. These retirements are ambiguous: the mechanical/incident split falls back to the estimated global share, and in Elo they carry half weight.<span class=\"src\">models/elo.py</span><span class=\"src\">models/circuits.py</span></li>\n<li>Race-control quirks. OpenF1 race control is not always tidy. In the case of Monza 2026, as the code's tests describe it, the safety car was deployed, the red flag arrived as an \"Other\" message (\"RED FLAG - RACE SUSPENDED\") after a SessionStatus \"SESSION ABORTED\", the race restarted on a SessionStatus \"SESSION STARTED\", and the safety car was never declared \"in this lap\". The lap-time model ends such unclosed windows at the leader's first green lap. A \"RACE WILL RESUME\" message does not close a red-flag window. The field-median rule (107%) is a second check that does not depend on race control.<span class=\"src\">models/laptime.py</span><span class=\"src\">tests/f1/test_pace.py</span></li>\n<li>No live timing. The site is rebuilt hourly from finished sessions. OpenF1 sessions are fetched 30 minutes after they end, and Jolpica results appear when Jolpica publishes them. Nothing updates during a session.<span class=\"src\">scripts/f1_openf1.py</span><span class=\"src\">.github/workflows/update_paddock.yml</span></li>\n<li>Thin markets. F1 prediction markets often have few two-sided quotes. Under the thin-market rule, a market is not published when too few runners are accounted for or the implied total is outside 0.8 to 1.3, so market comparisons are often unavailable, particularly for race winners and head-to-heads.<span class=\"src\">sources/markets.py</span></li>\n<li>Approximations. Lap length is inferred from the race distance, not measured. The simulator checks each car only against the nearest car ahead. Points tables before 1991 are simplified to 9-6-4-3-2-1, and dropped-score rules are not modelled. Braking points are limited by the telemetry sampling rate of about 3.7 Hz.<span class=\"src\">models/circuits.py</span><span class=\"src\">models/race_sim.py</span><span class=\"src\">telemetry.py</span></li>\n</ul>\n</section>\n";

/* How the pages themselves compute what they show (constants from this site's JS). */
const SITE_HTML = '<section id="m-site"><h2>How the pages compute what they show</h2>' +
  '<p>Most numbers on the site are computed by the Python build and read from the payloads. A few are computed in the browser, from those payloads:</p><ul>' +
  '<li><strong>Percentiles</strong> come from the payloads: a field percentile ranks a driver (or team) against everyone in that season, 100 = best, with lower-is-better metrics already flipped. The teammate percentile ranks the driver only against drivers who shared his car that season.</li>' +
  '<li><strong>Head to head</strong> (driver, team and compare pages) is counted from the two race logs over the rounds both started: qualifying goes to the better qualifying position; the race goes to the better classified finish, or to the driver who was classified when the other was not, and is not counted when neither was classified. A classified finish is Jolpica status "Finished", "+n Lap(s)" or "Lapped".</li>' +
  '<li><strong>Expected points</strong> on the driver page are summed from each round\'s stored forecast (the post-qualifying simulation when present, else the pre-qualifying one, plus the sprint forecast).</li>' +
  '<li><strong>The lab</strong> can shrink a driver-season towards the median of the group on screen with 3 races of prior: (races × value + 3 × median) / (races + 3). Labelled drivers are the ten with the largest sum of standard scores on both axes in the better direction; the ranked table uses the same score.</li>' +
  '<li><strong>Compare</strong> counts a metric as won when one side\'s percentile is higher; the verdict lists the three largest percentile gaps each way. When the two drivers come from different seasons, each percentile is against its own season\'s field.</li>' +
  '<li><strong>The telemetry lab</strong> overlays the stored fastest-lap traces (10 m spacing). Any other lap is fetched from OpenF1 car_data for the lap\'s time window, distance is integrated from speed and rescaled to the session\'s reference lap length, then resampled every 10 m. Time along the lap is the integral of 10 m / speed, scaled so it adds up to the lap time; the delta is the difference of the two. The map splits the lap into 50 m segments and colours each by the driver who took less time over it. Corner minimum speed and braking point come from the telemetry summary when the lap is in it, else from the trace with the same windows as the build (±80 m around the apex; braking start within 400 m before it).</li>' +
  '<li><strong>Calibration</strong> reliability bins show ±2 binomial standard errors at the bin\'s mean forecast, sqrt(p(1−p)/n).</li></ul></section>';

/* Driver value, the driver-swap simulator and constructors' strengths and needs (analytics/value.py). */
const VALUE_HTML = '<section id="m-value"><h2>Driver value, the driver-swap simulator and team needs</h2>' +
  '<p>F1 has no positions, so the <a href="#/value">value page</a> has one currency for drivers and one for cars, both from the season\'s car/driver decomposition (section on the decomposition) in percent of a lap, signed so that <strong>positive is faster</strong> (0.1% is about 0.09 s on a 90-second lap):</p><ul>' +
  '<li><strong>Pace above team-mate</strong>: minus the driver effect, for race pace and separately for qualifying, with its standard error. Team-mates share the car, so a driver is measured only against his team-mate, and the effect is shrunk toward zero (the prior is normal with the fitted driver spread): two equally fast team-mates both read 0, and a driver beside a weak team-mate looks better than he is. The standard errors (about 0.15% of a lap after a full season) are as large as most of the effects; read the ranking loosely.</li>' +
  '<li><strong>Pace above the field</strong>: minus the car\'s latest race-pace state plus the driver effect: what the driver and his car are worth together now.</li>' +
  '<li><strong>Constructors</strong> are ranked by the car\'s latest race-pace state (the random walk\'s last round), with the season mean of the observed rounds, the latest qualifying state and the change over the last five rounds (development).</li>' +
  '<li><strong>Trend</strong>: pace above team-mate against last season\'s, when both seasons have at least five races. Percentiles are among drivers with five races or more.</li></ul>' +
  '<p>The <a href="#/swap">driver-swap simulator</a> puts driver X in car Y: X swaps seats with W, one of Y\'s drivers, and both drivers\' and both teams\' expected points, title odds and final positions are re-simulated over the remaining rounds. For every remaining round\'s race inputs (the same ones the championship simulation uses) the swap gives X the seat W had: W\'s pace in that car plus the decomposition\'s driver difference, mu<sub>X</sub> = mu<sub>W</sub> + (drv<sub>X</sub> − drv<sub>W</sub>) × reference lap / 100; the seat\'s qualifying grid distribution (or its slot, once the grid is set); the car\'s mechanical retirement risk with X\'s own incident risk; and the team label, so the team\'s form walk and the constructors\' points follow the car. W gets X\'s seat the same way. Points already scored stay with the driver and the team that scored them. Every pair of current drivers on different teams is simulated (1,000 runs each) with the same random numbers as a baseline run, and the page adds each change to the published 20,000-run championship, so the comparison is not swamped by simulation noise. The table is cached on the race inputs\' numbers and recomputed only when they change (a new session or result).</p>' +
  '<p><strong>Strengths and needs</strong> on each team page grade the areas the models measure against the other teams (race and qualifying pace of the car, development through the season, mechanical reliability, tyre management, pit stops, strategy, straight-line speed, cornering), from the team catalogue\'s percentiles, plus the drivers by the mean team-mate Elo of the team\'s drivers (head-to-heads chained across career team-mates, the only driver measure here that compares drivers in different cars). Grades: A from the 80th percentile, B 60th, C 40th, D 20th, F below. The three strongest (60th percentile and up) and weakest (40th and down) are listed; a driver weakness gets the swaps that would add the most expected constructors\' points, from the swap table; a car or operations weakness gets a note, because there is no market for car performance and the models cannot price an upgrade. Contracts, availability and money are not considered.</p>' +
  '<span class="src">analytics/value.py</span><span class="src">models/championship.py</span><span class="src">models/decomposition.py</span></section>';

/* The fantasy layer (analytics/fantasy.py). */
const FANTASY_HTML = '<section id="m-fantasy"><h2>Fantasy: our points table, projections, value and the backtest</h2>' +
  '<p>The <a href="#/fantasy">fantasy page</a> scores every weekend with <strong>our own table</strong>, in the usual shape of F1 fantasy games but computed by us from Jolpica results and OpenF1 records. ' +
  '<strong>Nothing from the official F1 Fantasy game is used</strong> (prices, ownership, picks or scores): formula1.com\'s legal notices make its material "for your personal, non-commercial use only" and ask users not to "distribute copy extract or commercially exploit" it, and the game itself is a JavaScript app whose own terms could not be read without running it.</p>' +
  '<p><strong>Drivers.</strong> Qualifying P1–P10: 10 down to 1 (no time set −5). Grand Prix P1–P10: 25, 18, 15, 12, 10, 8, 6, 4, 2, 1; places gained or lost against the grid slot ±1 each (classified finishers; a pit-lane start is the last slot); fastest lap +10; not classified or disqualified −20. Overtakes +1 each: OpenF1 on-track passes with pit-stop changes, safety-car laps and passes on a car about to retire removed, up to 20 a race (2023 on; earlier seasons are scored "core", without them). Sprint P1–P8: 8 down to 1, places ±1, fastest lap +5, retirement −10. Driver of the day, sprint overtakes and sprint qualifying are left out. ' +
  '<strong>Constructors</strong>: both drivers, plus qualifying progression (both in Q3 +10, one +5, both in Q2 +3, one +1, neither −1) and the team\'s fastest stationary pit stop (under 2.0 s +20, 2.2 s +10, 2.5 s +5, 3.0 s +2) with +5 for the race\'s fastest, only where OpenF1 has stationary times.</p>' +
  '<p><strong>Projections</strong> come from the race simulation (same inputs as the race forecasts), played out per simulated weekend so that the floor and ceiling (10th and 90th percentiles) come with the mean. Before qualifying the grid is drawn from the qualifying model and the drawn slot doubles as the qualifying position (grid penalties are not modelled); once qualifying or the sprint has run, their actual points are used. A sprint uses the race inputs at the sprint distance with the same random numbers as its Grand Prix. ' +
  'Overtakes: λ = max(0.2, b0 + b1 × places gained + b2 × places lost + b3 × finished) × circuit factor × driver factor, b by least squares on every earlier OpenF1 race (counts capped at 20), the circuit factor shrunk with 1.5 races of prior and the driver factor with 15 races (a driver\'s overtake count barely carries from one season to the next). Pit points: the team\'s band points and share of fastest stops over its earlier races with stationary times (this season weight 1, last 0.35), shrunk to the field with 3 races. ' +
  'The <strong>rest of the season</strong> runs every remaining round in one simulation with the championship\'s season-level correlation (the pace error persists, team and driver form walk), so season totals carry an honest range.</p>' +
  '<p><strong>Value without prices.</strong> Fantasy prices broadly follow recent scoring, so our <em>form line</em> stands in: the season-to-date points per weekend, blended with last season\'s while the sample is small, (n × form + 3 × last) / (n + 3). Value = projection − form line. Value picks, differentials (projection rank at least two places above the form-line rank, outside the form top six), risers (car development, underlying pace ahead of form, or bad luck against the race forecasts) and fades come from the drivers in the top 60% of projections, so a backmarker reverting from a run of retirements is not sold as value. Tiers are optimal one-dimensional breaks (least within-tier squared error) into five groups.</p>' +
  '<p><strong>Backtest.</strong> Every Grand Prix weekend since 2012 is projected before qualifying with only the data before it (the walk-forward race inputs cached by the tuner, built live where missing) and scored with the same table; baselines are the season-to-date average, the previous weekend and last season\'s average. Mean absolute error, bias, the per-weekend Spearman rank correlation, the top-five overlap, the points scored by each method\'s top pick and the share of actual totals inside the 10–90% interval are on the fantasy page and in <code>data/fantasy_backtest.json</code>. The interval covers more than 80% partly because weekend scores are discrete (many drivers score exactly 0 or −20) and the interval is closed.</p>' +
  '<span class="src">analytics/fantasy.py</span><span class="src">models/race_sim.py</span><span class="src">models/championship.py</span></section>';

function renderMethodology(el, params) {
  const want = (params.rest || [])[0] || '';
  const tmp = document.createElement('div');
  tmp.innerHTML = METHOD_HTML + VALUE_HTML + FANTASY_HTML + SITE_HTML;
  const secs = Array.prototype.slice.call(tmp.querySelectorAll('section[id]')).map(s => {
    const h2 = s.querySelector('h2');
    const title = h2 ? h2.textContent : s.id;
    if (h2) h2.parentNode.removeChild(h2);
    return { id: s.id.replace(/^m-/, ''), title: title, html: s.innerHTML };
  });
  const toc = '<div class="doc-toc"><div class="doc-toc-head">Methodology</div><ol>' + secs.map(s => '<li><a href="#/methodology/' + esc(s.id) + '" data-target="method-' + esc(s.id) + '">' + esc(s.title) + '</a></li>').join('') +
    '</ol><div class="doc-toc-head" style="margin-top:10px">See also</div><ol><li><a href="#/glossary">Glossary</a></li><li><a href="#/calibration">Calibration</a></li><li><a href="#/disclaimer">Disclaimer and terms</a></li></ol></div>';
  const idx = PD.index() || {};
  const intro = '<div class="card"><div class="card-header">Methodology <span class="card-sub">Where the data comes from, how every model works, and where it is wrong. Written for a numerate fan; every constant is the one in the code, and each paragraph names the file it comes from.</span></div>' +
    '<div class="doc-meta">' + secs.length + ' sections' + (idx.updated_at ? ' · site updated ' + esc(PD.fmtStamp(idx.updated_at)) : '') + '</div></div>';
  el.innerHTML = '<div class="doc">' + toc + '<div class="doc-body">' + intro + secs.map((s, i) => '<div class="card" id="method-' + esc(s.id) + '"><div class="card-header">' + (i + 1) + '. ' + esc(s.title) +
    ' <a class="doc-anchor" href="#/methodology/' + esc(s.id) + '" title="Link to this section">#</a></div><div class="pad">' + s.html + '</div></div>').join('') + '</div></div>';
  el.querySelectorAll('.doc-toc a[data-target]').forEach(a => a.addEventListener('click', ev => {
    ev.preventDefault();
    const t = document.getElementById(a.dataset.target);
    if (t) t.scrollIntoView({ block: 'start' });
    history.replaceState(null, '', a.getAttribute('href'));
  }));
  if (want) { const t = document.getElementById('method-' + want.replace(/^m-/, '')); if (t) setTimeout(() => t.scrollIntoView({ block: 'start' }), 0); }
}

PD.route('glossary', renderGlossary);
PD.route('methodology', renderMethodology);
})(window.PD);
